// generated by tempo -- properties compiled to boolean safety monitors
module tempo_monitor(
  input clock,
  input dis,
  input [31:0] S_AXI_awaddr,
  input S_AXI_awvalid,
  input S_AXI_awready,
  input [31:0] S_AXI_wdata,
  input [3:0] S_AXI_wstrb,
  input S_AXI_wvalid,
  input S_AXI_wready,
  input [1:0] S_AXI_bresp,
  input S_AXI_bvalid,
  input S_AXI_bready,
  input [31:0] S_AXI_araddr,
  input S_AXI_arvalid,
  input S_AXI_arready,
  input [31:0] S_AXI_rdata,
  input [1:0] S_AXI_rresp,
  input S_AXI_rvalid,
  input S_AXI_rready
);
  // warm-up: history registers hold garbage until filled; asserting
  // before then would report artifacts of the monitor, not the DUT.
  reg [15:0] tempo_t = 16'd0;
  always @(posedge clock) tempo_t <= tempo_t + 16'd1;

  // ---- [assert] b_held (human)
  // intent: Once BVALID asserts it stays asserted until BREADY accepts it (AXI4-Lite: response may not be withdrawn)
  reg b_held_p1;
  wire b_held_ok = (!b_held_p1 || (S_AXI_bvalid));
  always @(posedge clock) begin
      b_held_p1 <= ((S_AXI_bvalid && !S_AXI_bready));
  end

  // ---- [assert] b_stable (human)
  // intent: BRESP is stable while BVALID waits for BREADY
  reg [1:0] b_stable_p1;
  reg b_stable_p2;
  wire b_stable_ok = (!b_stable_p2 || ((S_AXI_bresp) == b_stable_p1));
  always @(posedge clock) begin
      b_stable_p1 <= (S_AXI_bresp);
      b_stable_p2 <= ((S_AXI_bvalid && !S_AXI_bready));
  end

  // ---- [assert] r_held (human)
  // intent: Once RVALID asserts it stays asserted until RREADY accepts it
  reg r_held_p1;
  wire r_held_ok = (!r_held_p1 || (S_AXI_rvalid));
  always @(posedge clock) begin
      r_held_p1 <= ((S_AXI_rvalid && !S_AXI_rready));
  end

  // ---- [assert] r_stable (human)
  // intent: RDATA and RRESP are stable while RVALID waits for RREADY
  reg [31:0] r_stable_p1;
  reg [1:0] r_stable_p2;
  reg r_stable_p3;
  wire r_stable_ok = (!r_stable_p3 || (((S_AXI_rdata) == r_stable_p1) && ((S_AXI_rresp) == r_stable_p2)));
  always @(posedge clock) begin
      r_stable_p1 <= (S_AXI_rdata);
      r_stable_p2 <= (S_AXI_rresp);
      r_stable_p3 <= ((S_AXI_rvalid && !S_AXI_rready));
  end

  // ---- [assert] read_resp_bounded (human)
  // intent: Every accepted read address gets RVALID within 4 cycles
  reg [4:0] read_resp_bounded_pnd;
  wire [4:0] read_resp_bounded_pnd_cur = read_resp_bounded_pnd | {{4{1'b0}}, (S_AXI_arvalid && S_AXI_arready)};
  wire [4:0] read_resp_bounded_pnd_rem = (S_AXI_rvalid) ? (read_resp_bounded_pnd_cur & ~5'h1e) : read_resp_bounded_pnd_cur;
  wire read_resp_bounded_ok = (!read_resp_bounded_pnd_rem[4]);
  always @(posedge clock) begin
      read_resp_bounded_pnd <= dis ? 5'h0 : (read_resp_bounded_pnd_rem << 1);
  end

  // ---- [assert] write_resp_after_aw (human)
  // intent: Every accepted write address gets BVALID within 8 cycles
  reg [8:0] write_resp_after_aw_pnd;
  wire [8:0] write_resp_after_aw_pnd_cur = write_resp_after_aw_pnd | {{8{1'b0}}, (S_AXI_awvalid && S_AXI_awready)};
  wire [8:0] write_resp_after_aw_pnd_rem = (S_AXI_bvalid) ? (write_resp_after_aw_pnd_cur & ~9'h1fe) : write_resp_after_aw_pnd_cur;
  wire write_resp_after_aw_ok = (!write_resp_after_aw_pnd_rem[8]);
  always @(posedge clock) begin
      write_resp_after_aw_pnd <= dis ? 9'h0 : (write_resp_after_aw_pnd_rem << 1);
  end

  // ---- [assume] m_w_follows_aw (human)
  // intent: ENV: the master presents write data within 2 cycles of an accepted write address (discovered: without this, a master can send AW and starve W forever, so no response is ever owed)
  reg [2:0] m_w_follows_aw_pnd;
  wire [2:0] m_w_follows_aw_pnd_cur = m_w_follows_aw_pnd | {{2{1'b0}}, (S_AXI_awvalid && S_AXI_awready)};
  wire [2:0] m_w_follows_aw_pnd_rem = (S_AXI_wvalid) ? (m_w_follows_aw_pnd_cur & ~3'h7) : m_w_follows_aw_pnd_cur;
  wire m_w_follows_aw_ok = (!m_w_follows_aw_pnd_rem[2]);
  always @(posedge clock) begin
      m_w_follows_aw_pnd <= dis ? 3'h0 : (m_w_follows_aw_pnd_rem << 1);
  end

  // ---- [assume] m_w_held (human)
  // intent: ENV: the master holds WVALID (and stable payload is implied by the DUT capturing on the fire cycle) until WREADY accepts
  reg [1:0] m_w_held_pnd;
  wire [1:0] m_w_held_pnd_cur = m_w_held_pnd | {{1{1'b0}}, (S_AXI_wvalid && !S_AXI_wready)};
  wire [1:0] m_w_held_pnd_rem = (S_AXI_wvalid) ? (m_w_held_pnd_cur & ~2'h2) : m_w_held_pnd_cur;
  wire m_w_held_ok = (!m_w_held_pnd_rem[1]);
  always @(posedge clock) begin
      m_w_held_pnd <= dis ? 2'h0 : (m_w_held_pnd_rem << 1);
  end

  // ---- [assume] m_b_accepted (human)
  // intent: ENV: the master accepts a write response within 4 cycles (a stalled BREADY otherwise blocks the next transaction's response window)
  reg [4:0] m_b_accepted_pnd;
  wire [4:0] m_b_accepted_pnd_cur = m_b_accepted_pnd | {{4{1'b0}}, (S_AXI_bvalid)};
  wire [4:0] m_b_accepted_pnd_rem = (S_AXI_bready) ? (m_b_accepted_pnd_cur & ~5'h1f) : m_b_accepted_pnd_cur;
  wire m_b_accepted_ok = (!m_b_accepted_pnd_rem[4]);
  always @(posedge clock) begin
      m_b_accepted_pnd <= dis ? 5'h0 : (m_b_accepted_pnd_rem << 1);
  end

`ifdef TEMPO_FORMAL
  always @* if ((tempo_t >= 16'd2 && !dis)) assert(b_held_ok);
  always @* if ((tempo_t >= 16'd2 && !dis)) assert(b_stable_ok);
  always @* if ((tempo_t >= 16'd2 && !dis)) assert(r_held_ok);
  always @* if ((tempo_t >= 16'd2 && !dis)) assert(r_stable_ok);
  always @* if ((tempo_t >= 16'd2 && !dis)) assert(read_resp_bounded_ok);
  always @* if ((tempo_t >= 16'd2 && !dis)) assert(write_resp_after_aw_ok);
  always @* if ((tempo_t >= 16'd2 && !dis)) assume(m_w_follows_aw_ok);
  always @* if ((tempo_t >= 16'd2 && !dis)) assume(m_w_held_ok);
  always @* if ((tempo_t >= 16'd2 && !dis)) assume(m_b_accepted_ok);
`endif
`ifdef TEMPO_SIM
  always @(posedge clock) begin
    if ((tempo_t >= 16'd2 && !dis) && !b_held_ok) $error("TEMPO FAIL b_held: Once BVALID asserts it stays asserted until BREADY accepts it (AXI4-Lite: response may not be withdrawn)");
    if ((tempo_t >= 16'd2 && !dis) && !b_stable_ok) $error("TEMPO FAIL b_stable: BRESP is stable while BVALID waits for BREADY");
    if ((tempo_t >= 16'd2 && !dis) && !r_held_ok) $error("TEMPO FAIL r_held: Once RVALID asserts it stays asserted until RREADY accepts it");
    if ((tempo_t >= 16'd2 && !dis) && !r_stable_ok) $error("TEMPO FAIL r_stable: RDATA and RRESP are stable while RVALID waits for RREADY");
    if ((tempo_t >= 16'd2 && !dis) && !read_resp_bounded_ok) $error("TEMPO FAIL read_resp_bounded: Every accepted read address gets RVALID within 4 cycles");
    if ((tempo_t >= 16'd2 && !dis) && !write_resp_after_aw_ok) $error("TEMPO FAIL write_resp_after_aw: Every accepted write address gets BVALID within 8 cycles");
    if ((tempo_t >= 16'd2 && !dis) && !m_w_follows_aw_ok) $display("TEMPO ENV-VIOLATED m_w_follows_aw");
    if ((tempo_t >= 16'd2 && !dis) && !m_w_held_ok) $display("TEMPO ENV-VIOLATED m_w_held");
    if ((tempo_t >= 16'd2 && !dis) && !m_b_accepted_ok) $display("TEMPO ENV-VIOLATED m_b_accepted");
  end
`endif
endmodule
